const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function recordTable(d,{choice='',key=choice||'records',selected=[],interactive=false}={}){return `<div class="archive-table-wrap records-wrap"><table class="archive-table records-table" data-record-table="${esc(key)}"><caption>${esc(d.title||'L-0313 消杀台账')}</caption><thead><tr>${choice||interactive?'<th scope="col">标记</th>':''}${d.columns.map(v=>`<th scope="col">${esc(v)}</th>`).join('')}</tr></thead><tbody>${d.rows.map((row,i)=>`<tr data-record-row="${esc(choice?row[0]:key+'-'+i)}" class="${selected.includes(choice?row[0]:key+'-'+i)?'record-selected':''}">${choice?`<td><input type="radio" name="${choice}" value="${esc(row[0])}" aria-label="选择${esc(row[0])}行" ${selected.includes(row[0])?'checked':''} required></td>`:interactive?`<td><button type="button" data-row-toggle aria-pressed="${selected.includes(choice?row[0]:key+'-'+i)}" aria-label="标记${esc(row[0])}行">${selected.includes(choice?row[0]:key+'-'+i)?'已标记':'标记'}</button></td>`:''}${row.map((v,j)=>`<${j===0?'th scope="row"':'td'}>${esc(v)}</${j===0?'th':'td'}>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
export function tableCSV(d){return '\uFEFF'+[d.columns,...d.rows].map(row=>row.map(value=>{let cell=String(value??'');if(/^[=+@-]/.test(cell))cell="'"+cell;return '"'+cell.replaceAll('"','""')+'"';}).join(',')).join('\r\n');}
export function downloadLocal(content,name,type='text/csv;charset=utf-8'){const blob=content instanceof Blob?content:new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
